                         "  " + catchNormal + " = icmp eq i32 " + catchResult + ", 0\n"
                         "  br i1 " + catchNormal + ", label %" + catchBodyLabel +
                         ", label %" + catchErrorLabel + "\n"
                         + catchBodyLabel + ":\n"
                         "  call void @simp_exception_push(ptr " + catchFrame + ")\n";

